package com.carexpense.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Entity representing a single car expense record.
 *
 * <p>Maps to the CAR_EXPENSES table in Oracle Database.
 * Each instance holds all details for one expense entry.</p>
 */
@Entity
@Table(name = "CAR_EXPENSES")
public class Expense {

    /** Unique identifier for the expense record. Auto-generated by Oracle sequence. */
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "car_expenses_seq")
    @SequenceGenerator(name = "car_expenses_seq", sequenceName = "CAR_EXPENSES_SEQ", allocationSize = 1)
    @Column(name = "EXPENSE_ID")
    private Long id;

    /** Date on which the expense was incurred. */
    @Column(name = "EXPENSE_DATE", nullable = false)
    private LocalDate expenseDate;

    /** Category of the expense (e.g., Fuel, Maintenance, Insurance). */
    @Column(name = "CATEGORY", nullable = false, length = 100)
    private String category;

    /** Amount spent in Indian Rupees. */
    @Column(name = "AMOUNT", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    /** Optional description or notes for the expense. */
    @Column(name = "DESCRIPTION", length = 500)
    private String description;

    // -------------------------------------------------------
    // Constructors
    // -------------------------------------------------------

    /** Default no-arg constructor required by JPA. */
    public Expense() {
    }

    /**
     * Convenience constructor for creating a new expense record.
     *
     * @param expenseDate the date of the expense
     * @param category    the expense category
     * @param amount      the amount spent
     * @param description an optional description or note
     */
    public Expense(LocalDate expenseDate, String category, BigDecimal amount, String description) {
        this.expenseDate = expenseDate;
        this.category    = category;
        this.amount      = amount;
        this.description = description;
    }

    // -------------------------------------------------------
    // Getters and Setters
    // -------------------------------------------------------

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public LocalDate getExpenseDate() {
        return expenseDate;
    }

    public void setExpenseDate(LocalDate expenseDate) {
        this.expenseDate = expenseDate;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    // -------------------------------------------------------
    // toString
    // -------------------------------------------------------

    @Override
    public String toString() {
        return "Expense{" +
               "id=" + id +
               ", expenseDate=" + expenseDate +
               ", category='" + category + '\'' +
               ", amount=" + amount +
               ", description='" + description + '\'' +
               '}';
    }
}
